nodeSources.wait_sync:
# Wait for the Brain sync job and its thread summaries, at most about five minutes.
import time

from semoss import Insight


def run(scope):
    job = None
    for _ in range(30):
        time.sleep(10)
        job = Insight().run_pixel('BrainGetJob(kind=["sync"]);', raw=False)
        if not isinstance(job, dict):
            break
        if job.get("status") != "running" and not job.get("insightsPending"):
            break
    return job if isinstance(job, dict) else {"status": "unknown"}

nodeSources.gather:
# Gather what event planning needs: each pinned meeting's coming sittings, past sittings, related mail and chats,
# the Brain topics that track it, and its current sheet with the owner's edits marked.
import datetime
import json
import os
import re
from zoneinfo import ZoneInfo

import openpyxl
from semoss import Insight
from smssutil import smss_get_runtime_var

MAX_SITTINGS = 3
RELATED_THREADS = 3
HISTORY_DAYS = 90
# past sittings: one page over five weeks is enough to see who presented lately
PAST_DAYS = 35
SHEET = "Lineup"
# each meeting's sheet, in the owner's Collaboration storage (user assets), until the sheets can live in OneDrive
STORE = "collaboration/routines/event-planning"
STATE = "_routine"
# visible columns, in order; the key column sits last and hidden
COLUMNS = [("sitting", "Sitting"), ("start", "Start"), ("topic", "Topic"), ("presenter", "Presenter"),
           ("presenterEmail", "Presenter email"), ("minutes", "Minutes"), ("status", "Status"),
           ("materials", "Materials"), ("notes", "Notes"), ("source", "Source")]


def _value(name, value):
    # Pixel decodes \u escapes, so mail text can never open an <encode> tag in the Pixel.
    return name + "=[" + json.dumps(value).replace("<", "\\u003c") + "]"


def _pixel(reactor, **args):
    ret = Insight().run_pixel(reactor + "(" + ", ".join(_value(k, v) for k, v in args.items()) + ");", raw=True)
    last = ret[0]["pixelReturn"][-1]
    if "ERROR" in str(last.get("operationType")):
        raise RuntimeError(reactor + " failed: " + str(last.get("output")))
    return last.get("output") or {}


def _optional(reactor, **args):
    # History that cannot be read leaves a plan thinner instead of failing the run.
    try:
        return _pixel(reactor, **args)
    except Exception:
        return {}


def _clip(text, size):
    text = str(text or "").strip()
    return text if len(text) <= size else text[:size].rstrip() + " [...]"


def _at(value):
    return datetime.datetime.fromisoformat(str(value).replace("Z", "+00:00"))


def _title(text):
    return re.sub(r"\s+", " ", str(text or "")).strip().lower()


def _file_name(title):
    # the pinned title names the sheet; OneDrive refuses these characters in a name
    return re.sub(r'[\\/:*?"<>|#%]+', "-", title).strip(" .-")[:120] + ".xlsx"


def _events(start, end, zone, pages=3, **extra):
    # The calendar returns at most 100 events a page; three pages cover a busy three weeks.
    events, offset = [], 0
    while True:
        page = _pixel("MicrosoftCalendarListEvents", start=start.isoformat(), end=end.isoformat(), timeZone=str(zone),
                      includeBody=True, maxBodyChars=3000, limit=100, offset=offset, **extra)
        events += page.get("events") or []
        if not page.get("hasMore") or offset >= (pages - 1) * 100:
            return [e for e in events if not e.get("isCancelled") and not e.get("isAllDay")]
        offset += 100


def _matches(event, pin):
    if pin["kind"] == "series":
        return event.get("seriesId") == pin["id"]
    return event.get("id") == pin["id"]


def _sitting(event, zone):
    start, end = _at(event["start"]).astimezone(zone), _at(event["end"]).astimezone(zone)
    return {"date": start.strftime("%Y-%m-%d"), "day": start.strftime("%a %d %b %Y"), "start": start.strftime("%H:%M"),
            "end": end.strftime("%H:%M"), "minutes": int((end - start).total_seconds() // 60),
            "responseStatus": event.get("responseStatus"),
            "organizer": event.get("organizerName") or event.get("organizer"),
            "attendees": [{"name": a.get("name"), "email": a.get("address")} for a in event.get("attendees") or []][:30],
            "location": event.get("location"), "webLink": event.get("webLink"), "agenda": _clip(event.get("body"), 1500)}


def _related(title, today, threads):
    found = _optional("BrainSearchThreads", query=title, limit=RELATED_THREADS + 2,
                      **{"from": (today - datetime.timedelta(days=HISTORY_DAYS)).isoformat()})
    related = []
    # Only threads whose subject shares words with the meeting; a match on people alone is too loose.
    for hit in [h for h in found.get("items") or [] if "subject" in (h.get("matchedOn") or [])][:RELATED_THREADS]:
        messages = _optional("BrainGetThreadMessages", threadId=hit["threadId"], limit=3).get("messages") or []
        related.append({"type": hit.get("type"), "subject": hit.get("subject"), "lastAt": hit.get("lastAt"),
                        "topics": hit.get("topics"), "people": hit.get("people"),
                        "summary": threads.get(hit["threadId"], {}).get("summary"),
                        "messages": [{"from": m.get("fromName") or m.get("fromAddress"), "at": m.get("at"),
                                      "text": _clip(m.get("text"), 800)} for m in messages]})
    return related


def _tracked(topic, title, related):
    # A topic tracks a meeting when the owner linked the series to it or a related thread is filed under it.
    series = [_title(s) for s in topic.get("calendarSeries") or []]
    linked = any(s and (s == title or (len(s) > 3 and (s in title or title in s))) for s in series)
    return linked or any(topic.get("name") in (r.get("topics") or []) for r in related)


def _topic(topic):
    return {"name": topic.get("name"), "description": _clip(topic.get("description"), 600),
            "openGoals": [g.get("text") for g in topic.get("goals") or [] if g.get("status") == "open"],
            "openActionItems": [{"title": i.get("title"), "due": i.get("dueAt"), "priority": i.get("priority")}
                                for i in (topic.get("openActionItems") or [])[:10]],
            "people": [{"name": p.get("name"), "role": p.get("role")} for p in topic.get("people") or []][:15]}


def _cell(value):
    # what a cell says, the same however Excel stored it, so an untouched cell never reads as an edit
    if value is None:
        return ""
    if isinstance(value, datetime.datetime):
        return value.strftime("%Y-%m-%d") if (value.hour, value.minute) == (0, 0) else value.strftime("%H:%M")
    if isinstance(value, datetime.date):
        return value.isoformat()
    if isinstance(value, datetime.time):
        return value.strftime("%H:%M")
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    return str(value).strip()


def _read_sheet(path):
    # The hidden state sheet holds what the routine last wrote: a visible cell that differs is the owner's edit,
    # a visible row it does not know is the owner's row, and a key it wrote that is gone was deleted by the owner.
    book = openpyxl.load_workbook(path, data_only=True)
    if SHEET not in book.sheetnames:
        raise ValueError("The sheet has no " + SHEET + " tab")
    state = {}
    if STATE in book.sheetnames:
        for key, written, locked, deleted in book[STATE].iter_rows(min_row=2, max_col=4, values_only=True):
            if key:
                state[str(key)] = {"written": json.loads(written or "{}"), "locked": json.loads(locked or "[]"),
                                   "deleted": bool(deleted)}
    sheet = book[SHEET]
    header = [_cell(c) for c in next(sheet.iter_rows(min_row=1, max_row=1, values_only=True), [])]
    # find columns by header, so an owner who moved or added columns is still read right
    where = {name: header.index(label) for name, label in COLUMNS + [("key", "Key")] if label in header}
    rows, seen = [], set()
    for raw in sheet.iter_rows(min_row=2, values_only=True):
        values = {name: _cell(raw[i]) if i < len(raw) else "" for name, i in where.items()}
        if not any(values.get(name) for name, _ in COLUMNS):
            continue
        key = values.pop("key", "")
        known = state.get(key)
        if known and not known["deleted"] and key not in seen:
            seen.add(key)
            edited = [name for name, _ in COLUMNS if values.get(name, "") != str(known["written"].get(name, ""))]
            rows.append({"key": key, **values, "ownerEdited": sorted(set(known["locked"]) | set(edited))})
        else:
            rows.append({"key": "", **values, "ownerAdded": True})
    deleted = [key for key, known in state.items() if known["deleted"] or key not in seen]
    return {"rows": rows, "deleted": deleted}


def _sheet(name):
    path = STORE + "/" + name
    try:
        # copied into this run's folder under its own name; a failed copy is read as no sheet yet
        _pixel("CopyUserAssetsToInsight", filePath=[path])
    except Exception:
        return {"path": path, "name": name, "exists": False, "readable": True, "rows": [], "deleted": []}
    info = {"path": path, "name": name, "exists": True}
    try:
        info.update(_read_sheet(os.path.join(smss_get_runtime_var("ROOT"), name)))
        info["readable"] = True
    except Exception as e:
        # a sheet that cannot be read is left as it is, never overwritten
        info.update({"readable": False, "rows": [], "deleted": [], "error": _clip(str(e), 300)})
    return info


def run(scope):
    zone = ZoneInfo(str(scope.get("timezone") or "UTC"))
    now = datetime.datetime.now(zone)
    today = now.date()
    days = int(scope.get("days_ahead") or 21)
    pins = [p for p in scope.get("meetings") or [] if isinstance(p, dict) and p.get("id")]
    upcoming = _events(today, today + datetime.timedelta(days=days), zone)
    threads = {t["id"]: t for t in _optional("BrainListThreads", limit=100, offset=0, detail=True).get("items") or []}
    topics = [_optional("BrainGetTopic", topicId=t["id"]) for t in
              _optional("BrainListTopics", status="active", limit=50, offset=0).get("items") or []]
    meetings, missing = [], []
    for pin in pins:
        title = _title(pin["title"])
        # a sitting that has already ended today is history, not a lineup to plan
        sittings = [e for e in upcoming if _matches(e, pin) and e.get("responseStatus") != "declined"
                    and _at(e["end"]) > now]
        sheet = _sheet(_file_name(pin["title"]))
        if not sittings:
            missing.append(pin["title"])
        past = []
        if pin["kind"] == "series":
            try:
                past = [e for e in _events(today - datetime.timedelta(days=PAST_DAYS), today, zone, pages=1,
                                           subject=pin["title"]) if _matches(e, pin)]
            except Exception:
                past = []
        related = _related(pin["title"], today, threads)
        meetings.append({
            "pin": pin["id"], "kind": pin["kind"],
            "title": sittings[0].get("subject") if sittings else pin["title"],
            "sittings": [_sitting(e, zone) for e in sittings[:MAX_SITTINGS]],
            "pastSittings": [{"date": _at(e["start"]).astimezone(zone).strftime("%Y-%m-%d"),
                              "agenda": _clip(e.get("body"), 1000)} for e in past][-4:],
            "related": related,
            "trackedTopics": [_topic(t) for t in topics if t and _tracked(t, title, related)],
            "sheet": sheet})
    context = {"today": today.isoformat(), "daysAhead": days, "meetings": meetings,
               "notOnCalendar": missing}
    # the model sees the sheet rows, not where the file lives or when it changed
    context["agentView"] = {"today": context["today"], "notOnCalendar": missing, "meetings": [
        {**{k: v for k, v in m.items() if k != "sheet"},
         "currentRows": m["sheet"]["rows"], "deleted": m["sheet"]["deleted"]} for m in meetings]}
    return context
